const uint8_t *OwnDollPicture(int16_t picture, int32_t *size)
{
	for (uint16_t i = 0; i < sizeof Pictures / sizeof Pictures[0]; i++) {
		if (Pictures[i].picture == picture) {
			*size = Pictures[i].size;
			return Pictures[i].data;
		}
	}
	return 0;
}

