const struct DerivedDollPicture *FindDerivedDollPicture(int16_t picture)
{
	for (uint16_t i = 0; i < sizeof Derived / sizeof Derived[0]; i++)
		if (Derived[i].picture == picture)
			return &Derived[i];
	return 0;
}
